pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy >= 0);
        uint256 cntBefore;
        try c.depositsCount() returns (uint256 __r) { cntBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint256 cntAfter;
        try c.depositsCount() returns (uint256 __r) { cntAfter = __r; } catch { return; }
        uint balAfter = address(c).balance;
        assertTrue(!reverted && balAfter == 0 && cntAfter == cntBefore && cntBefore >= 0 && balBefore >= 0);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
